window.STOTT = window.STOTT || {};
window.STOTT.apparatus = window.STOTT.apparatus || {};
window.STOTT.apparatus.mat = {
  warmup: [
    { name: "Breathing", level: "Warm-Up", page: "18", startingPosition: "Seated on the mat, spine and pelvis neutral and vertical.\nKnees bent, feet flat on the mat, holding the shins.\nScapulae stabilized.", pelvis: "Neutral to posterior tilt as the spine folds forward", spine: "Sequentially flexes forward over the legs, then rolls back up", breathing: "Exhale to initiate from the top of the head and sequentially articulate the spine into flexion forward, relaxing over the legs\nThen, folded forward: inhale through the nose, feeling the back and sides of the ribcage expand\nExhale through pursed lips, allowing the ribcage to close — 3–5 breaths\nOn the last exhale, initiate from the tail and sequentially articulate the spine, rolling back up to the starting position\nComplete 2–3 repetitions.", focus: "Relaxes the erector spinae, neck and shoulder muscles, and helps access the areas of the rib cage important to breath patterns throughout the rest of the workout — the 3D breathing happens while folded forward over the legs, not sitting upright.", cues: ["Breathe into my hands on the sides of your ribs.", "Stretch your sports bra in all directions."], modifications: ["Breathing forward on the Arc Barrel — sit on the mat with the knees over the Barrel.", "Flex-Band around the back for feedback.", "Side-breathing against a barrel."] , script: { lines: ["Let's start with Breathing. Come to seated, spine tall, knees bent, holding onto your shins.", "Exhale to fold your spine forward over your legs, relaxing there. Now take three to five breaths in that folded position — inhale through the nose, feeling your ribs expand sideways and into your back; exhale through pursed lips, feeling them close.", "On your last exhale, roll back up to sitting, starting the roll from your tailbone. This relaxes your erector spinae and shoulders while opening up the rib cage you'll need for the rest of the workout."] } },
    { name: "Imprint & Release", level: "Warm-Up", page: "19", startingPosition: "Supine, knees bent.", pelvis: "Alternating Neutral and Imprint", spine: "Neutral to slight lumbar flexion", breathing: "Four breaths, one per transition.", focus: "Teaches the two pelvic placements side by side so the client feels the difference.", cues: ["Balance the bowl of water on your pelvis — then gently spill it toward imprint."], modifications: ["Four breaths — to slow down the movement and create awareness."] , script: { lines: ["Let's move into Imprint and Release. Come to supine, knees bent, feet flat.", "Inhale in neutral. Exhale to gently tilt your pelvis into imprint, lengthening your low back toward the mat. Inhale back to neutral. Four breaths, one per transition.", "Imagine a bowl of water balanced on your pelvis — use your transversus abdominis and rectus abdominis to gently spill it toward imprint, then rebalance it back to neutral."] } },
    { name: "Hip Release", level: "Warm-Up", page: "20", startingPosition: "Supine, pelvis and spine neutral. Knees flexed, feet abducted hip-distance apart on the mat. Arms long by the sides, palms down.", pelvis: "Neutral (imprinted modification if neutral can't be stabilized)", spine: "Neutral", breathing: "Inhale to release the hip joint and rotate the leg laterally, letting it fall out to the side as the knee extends and the foot slides away from the torso\nExhale to rotate the leg medially at the hip, letting it fall across the midline as the knee flexes and the foot slides back in toward the torso\nComplete 3 repetitions in this direction, then reverse — rotate medially to slide the foot away, laterally to slide it back in — 3 more times. Repeat on the other leg.", focus: "Mobilizes the hip joint while keeping the pelvis stable — don't grip the muscles around the hip to produce the movement, simply let the leg fall gently from one side to the other.", modifications: ["Imprinted — can be performed with the pelvis imprinted instead of neutral if neutral cannot be stabilized during extension of the leg.", "Start with only the leg sliding, no rotation.", "Add a leg lift and toe taps."] , script: { lines: ["Let's move into Hip Release. Come to supine, knees bent, feet hip-distance apart on the mat.", "Inhale to release your hip and let your leg rotate out, knee extending and foot sliding away from you. Exhale to rotate the hip in, knee bending and foot sliding back across the midline toward you.", "Let your leg fall gently from one side to the other — don't grip to produce the movement — and keep your pelvis anchored and still the whole time."] } },
    { name: "Spinal Rotation", level: "Warm-Up", page: "21", startingPosition: "Side-lying on the mat, hips and knees flexed. Arms extended forward on the mat at shoulder height, palms together.", pelvis: "Neutral — hips stay in the same flexed position throughout", spine: "Thoracic rotation only", breathing: "Inhale to reach the top arm toward the ceiling, gaze forward\nExhale to continue reaching the arm out to the side, letting the upper torso rotate as the front of the chest opens to face the ceiling\nInhale to stay, breathing into the side of the ribcage\nExhale to engage the abdominals and rotate the torso back to the starting position.\nComplete 2–3 repetitions on each side.", focus: "Maintain the hips in the same position with the legs adducted while the upper torso rotates — this is thoracic rotation only; the top arm doesn't need to touch the mat behind you.", modifications: ["Supine, spine imprinted, pelvis in a slight posterior tilt, legs in tabletop, arms long out to the side — exhale to rotate the lower torso, letting both legs lower toward the mat on one side while the shoulders stay flat on the mat; inhale to breathe into the ribcage; exhale to rotate back to center. Suited to those with more abdominal strength.", "Head resting on a foam cushion, for some individuals, to avoid cervical discomfort."] , script: { lines: ["Let's move into Spinal Rotation. Come to side-lying, hips and knees bent, arms reaching forward at shoulder height, palms together.", "Inhale to reach your top arm toward the ceiling. Exhale to continue reaching it out to the side, letting your upper torso rotate and your chest open to face the ceiling. Inhale to stay and breathe into your ribcage.", "Exhale to engage your obliques and rotate back to center. Your hips and legs stay completely still — this is rotation through your thoracic spine only."] } },
    { name: "Cat Stretch", level: "Warm-Up", page: "22", startingPosition: "Quadruped, arms under the shoulders, knees under the hips, knees abducted hip-distance apart.\nPelvis and spine neutral.", pelvis: "Neutral to posterior tilt during flexion", spine: "Moving flexion ↔ extension", breathing: "Exhale to articulate the spine into flexion from tailbone to head\nInhale to keep the abdominals engaged and expand the back of the rib cage\nExhale to articulate into slight extension from tailbone to head.", focus: "Even, segmental flexion and extension sequenced continuously from tailbone to head, keeping the abdominals engaged to support the lumbar spine in extension.", modifications: ["Feet off the end of a raised mat, for tightness through the dorsal (top) portion of the foot.", "Reverse the sequencing direction for variety.", "Sequence from the center of the spine, with the head and tail articulating toward each other simultaneously.", "Two breaths — exhale on flexion, inhale on extension, to speed up the exercise once abdominal engagement on extension is familiar."] , script: { lines: ["Let's move into Cat Stretch. Come to quadruped, hands under your shoulders, knees under your hips, hip-distance apart.", "Exhale to round your spine from tailbone to head. Inhale, keeping your abdominals engaged, to expand the back of your ribcage. Exhale again to articulate into a slight extension, tailbone to head.", "Move one vertebra at a time, evenly, in both directions — keep your abdominals supporting your low back as you extend."] } },
    { name: "Hip Rolls", level: "Warm-Up", page: "23", startingPosition: "Supine, pelvis and spine neutral.\nKnees bent, feet abducted hip-distance apart on the mat, arms long by the sides, palms down.", pelvis: "Imprinted during the lift", spine: "Articulated flexion", breathing: "Smooth, continuous.", focus: "Segmental spinal articulation off the mat — a preview of Shoulder Bridge.", modifications: ["Begin with the feet on top of the Arc Barrel, to permit greater mobility through the lumbar spine, especially for those with lordosis."] , script: { lines: ["Let's move into Hip Rolls. Come to supine, knees bent, feet hip-distance apart, arms long by your sides.", "Exhale to curl your pelvis and lower spine up off the mat into imprint, one vertebra at a time. Inhale to hold, exhale to roll back down.", "Keep the movement smooth and segmental, using your gluteus maximus and hamstrings to lift and your deep abdominals to control it — this is your preview of Shoulder Bridge."] } },
    { name: "Scapula Isolation", level: "Warm-Up", page: "24", startingPosition: "Supine, pelvis and spine neutral.\nKnees bent, feet abducted hip-distance apart on the mat.\nArms long, reaching to the ceiling, palms facing each other.\nScapulae neutral.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to protract the scapulae\nExhale to return to neutral\nInhale to retract the scapulae\nExhale to return to neutral.", focus: "Isolates scapular protraction/retraction before any limb loading.", modifications: ["Seated — movement of the scapulae is not hindered by the mat.", "Flex-Band held behind the back for resistance/feedback."] , script: { lines: ["Let's move into Scapula Isolation. Come to supine, knees bent, arms reaching straight up to the ceiling, palms facing each other.", "Inhale to protract, letting your shoulder blades widen apart. Exhale to return to neutral. Inhale to retract, drawing them together. Exhale to return to neutral.", "Isolate the movement at your shoulder blades only, using your serratus anterior to protract and your rhomboids to retract — keep your ribs and spine completely still."] } },
    { name: "Arm Circles", level: "Warm-Up", page: "25", startingPosition: "Supine, pelvis and spine neutral.\nKnees bent, feet abducted hip-distance apart on the mat.\nArms long by the sides, palms down.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Inhale to reach the arms toward the ceiling and overhead\nExhale to circle the arms out to the sides and around to the hips.\n3–5 reps, then reverse direction for 3–5 more.", focus: "Mobilizes the shoulder girdle through a full circular range while the ribcage stays anchored.", modifications: ["Arm scissors as an alternate arm pattern."] , script: { lines: ["Let's move into Arm Circles. Come to supine, knees bent, arms long by your sides.", "Inhale to reach your arms toward the ceiling and overhead. Exhale to circle them out to the sides and back down to your hips. Three to five reps, then reverse.", "Keep your ribcage anchored and quiet, letting your deltoids and rotator cuff move the arms through the circle."] } },
    { name: "Head Nods", level: "Warm-Up", page: "26", startingPosition: "Supine, pelvis and spine neutral. Knees flexed, feet abducted hip-distance apart on the mat. Arms long by the sides, palms down.", pelvis: "Neutral", spine: "Cervical flexion only (cranio-vertebral nod)", breathing: "Inhale to lengthen the back of the neck, leaving the head on the mat, with a slight nod\nExhale to return to neutral\nRepeat 3 more times.", focus: "Isolates the deep neck flexors (longus colli and longus capitis) that will initiate every abdominal-flexion exercise — avoid jamming the chin into the chest or over-flexing the cervical spine." , script: { lines: ["Let's move into Head Nods. Come to supine, knees bent, feet flat on the mat.", "Inhale to lengthen the back of your neck, leaving your head resting on the mat, with just a slight nod. Exhale to return to neutral.", "Keep your head resting on the mat — this is a small nod, not a lift, and it wakes up your longus colli and longus capitis, the deep muscles at the front of your neck."] } },
    { name: "Elevation & Depression of Scapulae", level: "Warm-Up", page: "27", startingPosition: "Supine, pelvis and spine neutral.\nKnees bent, feet abducted hip-distance apart on the mat.\nArms long by the sides, palms down.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to slide the shoulders up toward the ears, elevating the scapulae\nExhale to slide the shoulders away from the ears, depressing the scapulae.", focus: "Isolates scapular elevation/depression — the last scapular plane before combining movements in the workout." , script: { lines: ["Let's move into Elevation and Depression of the Scapulae. Come to supine, knees bent, arms long by your sides.", "Inhale to slide your shoulders up toward your ears. Exhale to slide them back down, away from your ears.", "Feel your upper trapezius and levator scapulae lifting on the inhale, then your lower trapezius gliding your shoulder blades back down flat against your ribcage, like butter melting down a warm pan."] } },
  ],
  essential: [
    { name: "Ab Prep", level: "Essential", page: "30", startingPosition: "Supine, knees bent.", pelvis: "Neutral", spine: "Thoracic flexion (cranio-vertebral nod first)", breathing: "Inhale to prepare/lengthen\nExhale to curl the head/shoulders off the mat.", targetMuscles: "Rectus abdominis, obliques, transversus abdominis.", focus: "Establishes the abdominal curl pattern and cranio-vertebral flexion used throughout the rest of the mat repertoire.", cues: ["Nod your chin slightly, then curl up and over an imaginary beach ball."], faults: ["Pulling on the neck with the hands — cue lengthening the back of the neck instead.", "Ribs flaring on the curl — keep the front ribs knitting down."], modifications: ["Hands behind the head for support.", "Hold a Fitness Circle® between the knees.", "Barrel under the knees.", "Flex-Band under the spine.", "Arms crossed on chest.", "Pad/ball between the knees."] , script: { lines: ["Let's move into Ab Prep. Come to supine, knees bent, feet flat on the mat.", "Inhale to prepare and lengthen. Exhale to nod your chin, then curl your head and shoulders up off the mat.", "Curl up and over, as if reaching over an imaginary beach ball — feel your rectus abdominis and obliques doing the lifting, lengthen the back of your neck rather than pulling on it, and keep your front ribs knitting down, not popping open."] } },
    { name: "Breast Stroke Prep", level: "Essential", page: "32", startingPosition: "Prone, neutral pelvis.\nLegs extended along the mat, adducted or abducted hip-distance apart, parallel, ankles plantar-flexed, toes gently pointed.", pelvis: "Neutral", spine: "Neutral to extension", breathing: "Two breaths per repetition (inhale to prepare, exhale to extend).", targetMuscles: "Erector spinae, deep back extensors, scapular stabilizers.", focus: "Three hand positions, each a heavier lever than the last, preparing thoracic extension and scapular stabilization for full Breast Stroke later in the workout.", positions: [
      { label: "Hands by Shoulders", detail: "Arms bent, hands by the shoulders, palms down. Exhale to open the front of the shoulders by retracting the scapulae to neutral, then extend the thoracic and cervical spine — mimics the higher, more extended position in full Breast Stroke." },
      { label: "Hands by Hips (Hover)", detail: "Arms long by the sides, hands by the hips, palms facing the body, shoulders relaxed forward. Exhale to reach the fingertips toward the toes as the torso extends into a long, low line — mimics the long, low dive position in full Breast Stroke." },
      { label: "Hands under Forehead", detail: "Arms bent, hands under the forehead, kept in contact with it throughout. The heaviest lever of the three — mid-back extensors work harder here than in Hands by Hips — also mimics the long, low dive position in full Breast Stroke." },
    ], modifications: ["Prone on the Arc Barrel, knees resting on the floor so the lumbar spine is in slight flexion — isolates extension to the upper/mid back and avoids extending the lumbar spine.", "Thin pad under the ASIS, to prevent anterior pelvic tilt.", "On two breaths — incorporate an inhale on the extension; can be used with Preps 1, 2, and 3.", "Upper body off the end of the mat, starting flexed over the raised end and extending only to a flat-back position — useful for kyphosis.", "Sponge or ball between the knees, to aid adductor connection."] , script: { lines: ["Let's move into Breast Stroke Prep. Come to prone, legs extended, hip-distance apart, pelvis neutral.", "We'll work through three hand positions, each a little heavier than the last — hands by your shoulders, then hands by your hips, then hands under your forehead. Exhale to open across the front of your shoulders and extend through your upper back; inhale to release back down.", "Each position mimics a piece of the full Breast Stroke — build the extension from your erector spinae and deep back extensors lifting your upper back, not by cranking your low back."] } },
    { name: "Shell Stretch", level: "Essential", page: "35", startingPosition: "Kneeling rest position (child's pose).", pelvis: "Posterior tilt", spine: "Flexion", breathing: "Slow, restorative breathing.", focus: "A rest/reset position used between exercises to release the low back — appears repeatedly through the workout.", modifications: ["Supine position — if Shell Stretch is uncomfortable, substitute lying supine and hug the knees toward the chest while breathing.", "Seated on the mat, flexed forward, knees bent, hugging the legs.", "Sit on a yoga block."] , script: { lines: ["Let's move into Shell Stretch. Come to kneeling, sit back onto your heels, arms reaching forward.", "Inhale to lengthen through your spine. Exhale to release deeper into the stretch, sitting your hips back toward your heels.", "Let your whole spine round evenly — this is a rest position, so let it be restorative between exercises."] } },
    { name: "The Hundred", level: "Essential", page: "36", startingPosition: "Supine, tabletop or legs extended on the diagonal.", pelvis: "Imprinted", spine: "Thoracic flexion", breathing: "Staccato breathing — 5 short pumping inhales, 5 short pumping exhales, repeated to 100 total pumps.", targetMuscles: "Transversus abdominis, rectus abdominis, obliques, hip flexors (holding the legs).", focus: "Builds abdominal endurance and stamina while stabilizing the pelvis against the pumping arms.", cues: ["Scoop your abs as you pump your arms — energy out through the fingertips."], faults: ["Neck straining forward — keep the cranio-vertebral nod, don't jam the chin.", "Ribs popping up — keep them knitted down."], modifications: ["Head and feet on the mat.", "Feet on the mat in neutral.", "Tabletop legs, head on the mat.", "Flex the hips and knees for five counts on the inhale to return to tabletop, then extend the legs for five counts on the exhale — challenges coordination.", "Shoulders on the Arc Barrel — assists the abdominals with thoracic flexion; resting the head on the barrel too can eliminate neck tension while encouraging thoracic flexion.", "Spine Supporter — develops abdominal strength and/or alleviates neck tension due to weak cervical flexors or abdominals.", "Breathe in a staccato rhythm to help establish the full breath pattern and avoid holding the breath.", "Circle between the knees/ankles.", "Flex-Band around the feet.", "Pad/ball between the knees/ankles."] , script: { lines: ["Let's move into The Hundred. Come to supine, legs in tabletop or extended on the diagonal, arms reaching long by your sides.", "Curl up into your abdominal flexion, then pump your arms up and down in a staccato rhythm — five short breaths in, five short breaths out, up to a hundred.", "Scoop your transversus abdominis and rectus abdominis as you pump, sending the energy out through your fingertips — keep the nod in your chin, don't let your ribs pop up."] } },
    { name: "Half Roll Back", level: "Essential", page: "39", startingPosition: "Seated, knees bent, feet flat, hip-distance apart.", pelvis: "Posterior tilt as the roll begins", spine: "Lumbar flexion", breathing: "Inhale to prepare\nExhale to roll back into a C-curve\nInhale to roll forward and return to start.", targetMuscles: "Deep abdominals maintaining spinal flexion, hip flexors and hip extensors controlling the pelvic roll.", focus: "Segmental lumbar articulation against gravity — the building block for Roll Up.", modifications: ["Flex-Band around the feet for counter-tension.", "Circle between the thighs.", "Pad/ball between the knees."] , script: { lines: ["Let's move into Half Roll Back. Come to seated, knees bent, feet flat, hip-distance apart.", "Inhale to prepare. Exhale to roll back into a C-curve. Inhale to roll back up to your starting position.", "Initiate the roll from your deep abdominals tilting the pelvis under, not by leaning back with a straight spine — this is the building block for Roll Up."] } },
    { name: "Roll Up", level: "Essential", page: "40", startingPosition: "Supine, legs extended.", pelvis: "Neutral to imprint during the roll", spine: "Sequential flexion", breathing: "Inhale to reach arms overhead\nExhale to curl up and over.", targetMuscles: "Rectus abdominis, obliques, hip flexors, hamstrings (flexibility).", focus: "Full sequential spinal articulation from supine to seated and back.", faults: ["Momentum/swinging instead of sequential control — slow the tempo and articulate one vertebra at a time.", "Legs popping up off the mat — anchor through the heels."], modifications: ["Half roll up, legs flexed.", "Half roll up, legs extended.", "Full roll up, legs flexed.", "Flex-Band around the feet.", "Pad/ball between the knees.", "Arms by the ears.", "Hold onto a Fitness Circle®."] , script: { lines: ["Let's move into Roll Up. Come to supine, legs extended.", "Inhale to reach your arms overhead. Exhale to curl your head and chest up and roll all the way forward over your legs.", "Articulate one vertebra at a time using your rectus abdominis and obliques — no swinging or using momentum — and keep your legs anchored through your hip flexors so they don't pop up off the mat."] } },
    { name: "One Leg Circle", level: "Essential", page: "42", startingPosition: "Supine, one leg extended to the ceiling (or bent).", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale for half the circle\nExhale for the other half.", targetMuscles: "Hip flexors, adductors/abductors, deep core stabilizers of the pelvis.", focus: "Hip dissociation from a stable pelvis — the pelvis must not rock as the leg circles.", modifications: ["Bend both knees.", "Bend either knee.", "Small, quick circles.", "Foot in a Flex-Band.", "Flex-Band around the thigh.", "Hold a circle over the chest."] , script: { lines: ["Let's move into One Leg Circle. Come to supine, one leg extended toward the ceiling.", "Inhale for half the circle, exhale for the other half, keeping your pelvis completely still as the leg moves.", "The circle happens at your hip joint only, driven by your hip flexors and adductors/abductors — if you feel your deep core stabilizers losing the pelvis and it starts to rock, make the circle smaller."] } },
    { name: "Spine Twist", level: "Essential", page: "44", startingPosition: "Seated, legs long and together, ankles dorsiflexed.", pelvis: "Neutral", spine: "Axial elongation with rotation", breathing: "Inhale to prepare and lengthen\nExhale in three pulses rotating further each time\nInhale to lengthen and return to center.", targetMuscles: "Obliques (rotators), deep spinal rotators.", focus: "Pure axial rotation while keeping the pelvis square and still.", modifications: ["Sit on a cushion, the mat's edge, or cross-legged.", "Reverse the breathing pattern.", "Flex the back elbow on rotation.", "Hold a circle against the rib cage.", "Sit on a Flex-Band.", "Pads between the knees."] , script: { lines: ["Let's move into Spine Twist. Come to seated tall, legs long and together, arms out to the sides in a T.", "Inhale to prepare and lengthen. Exhale in three small pulses, rotating a little further each time. Inhale to lengthen and return to center.", "Grow tall through the crown before you turn, and let your obliques and deep spinal rotators drive the turn from your ribcage — keep your pelvis square and still the whole time."] } },
    { name: "Rolling Like a Ball", level: "Essential", page: "46", startingPosition: "Balanced on the sit bones, eyes toward the knees, legs together, hips/knees flexed, toes off the mat.", pelvis: "Posterior tilt", spine: "Full flexion (C-curve)", breathing: "Inhale to roll back\nExhale to roll up to balance.", targetMuscles: "Deep abdominals, obliques (maintaining the C-curve).", focus: "Balance and control of a consistent C-curve through a rolling motion.", faults: ["Rolling onto the neck — keep the roll between the shoulder blades and the sacrum.", "Losing the C-curve and flattening the back mid-roll."], modifications: ["Prep with feet on the mat.", "Prep with feet off the mat.", "Reverse breathing.", "Hold a Fitness Circle®.", "Pad/ball between the knees."] , script: { lines: ["Let's move into Rolling Like a Ball. Come to balance on your sit bones, knees and hips flexed, eyes toward your knees, toes off the mat.", "Inhale to roll back onto your shoulder blades. Exhale to roll back up to balance.", "Keep a consistent C-curve throughout, held by your deep abdominals and obliques — roll only between your shoulder blades and your sacrum, never onto your neck."] } },
    { name: "Single Leg Stretch", level: "Essential", page: "48", startingPosition: "Supine flexion position, legs in tabletop, hands by the knee.", pelvis: "Imprinted", spine: "Thoracic flexion", breathing: "Exhale to extend one leg on the diagonal\nInhale to switch legs\nRepeat, alternating sides.", targetMuscles: "Rectus abdominis, obliques, hip flexors.", focus: "Coordination of alternating limb movement while holding thoracic flexion and pelvic stability.", modifications: ["Head on the mat.", "Double breath — exhale to extend each leg, then inhale to extend each, to increase the pace of the exercise.", "Flex the hip only to 90°.", "Scoop the foot as the leg extends.", "Hold a Fitness Circle®.", "Shoulders on the Arc Barrel.", "Spine Supporter — develops abdominal strength and/or reduces neck tension due to weakness in the cervical flexors or abdominals.", "Hands behind the head."] , script: { lines: ["Let's move into Single Leg Stretch. Come to supine, curled up into flexion, one knee hugged to your chest, the other leg extended.", "Exhale to switch legs, drawing the new knee in as the other extends. Two counts per switch.", "Hug the bent knee in with your hip flexors without letting your pelvis tuck further, and let your rectus abdominis and obliques hold the extended leg at a height you can control."] } },
    { name: "Obliques", level: "Essential", page: "50", startingPosition: "Supine rotation/flexion position, legs in tabletop, hands behind the head.", pelvis: "Imprinted", spine: "Flexion with rotation", breathing: "Exhale to extend one leg and rotate the upper body toward the opposite side\nInhale to return to center and switch legs\nRepeat, alternating sides.", targetMuscles: "External and internal obliques.", focus: "Adds rotation to the Single Leg Stretch pattern — elbow reaches toward the opposite knee without pulling the neck.", modifications: ["Feet on the mat.", "Tabletop legs stay still.", "Double breath — inhale while rotating the upper body to both sides, then exhale while rotating to both sides, to increase the pace of the exercise.", "Flex the hip only to 90°.", "Shoulders on the Arc Barrel.", "Spine Supporter — develops abdominal strength and/or reduces neck tension due to weakness in the cervical flexors or abdominals.", "Hold a Fitness Circle Resistance Ring — reach the ring past the flexed knee as the upper body rotates to that side, adding upper-body resistance and scapular awareness."] , script: { lines: ["Let's move into Obliques. Come to supine, curled up, legs in tabletop, hands behind your head.", "Exhale to extend one leg while rotating your upper body toward the opposite knee. Inhale to return to center and switch sides.", "Rotate from your external and internal obliques toward your knee — don't pull on your neck to get there."] } },
    { name: "Double Leg Stretch", level: "Essential", page: "54", startingPosition: "Supine flexion position, legs in tabletop, hands reaching toward the ankles.", pelvis: "Imprinted", spine: "Thoracic flexion", breathing: "Exhale to reach the arms overhead and extend the legs out\nInhale to circle the arms around and flex the knees back to tabletop.", targetMuscles: "Rectus abdominis, hip flexors, shoulder stabilizers.", focus: "Maintains thoracic flexion and pelvic stability through simultaneous full-body extension and flexion.", modifications: ["Reverse breathing — increases the challenge to stabilize the spine and pelvis during the reaching motion on the inhale.", "Spine supporter.", "Shoulders on the Arc Barrel.", "Feet on the mat.", "Fitness Circle® between the ankles.", "Flex-Band around the feet.", "Pad/ball between the ankles/knees."] , script: { lines: ["Let's move into Double Leg Stretch. Come to supine flexion, legs in tabletop, hands reaching toward your ankles.", "Exhale to reach your arms overhead and your legs long. Inhale to circle your arms around and draw your knees back to tabletop.", "Keep your rectus abdominis holding your thoracic flexion and your pelvis stable, with your shoulder stabilizers controlling the arms, the entire time your arms and legs are moving."] } },
    { name: "Scissors", level: "Essential", page: "56", startingPosition: "Supine flexion, legs extended to the ceiling, parallel and together, plantar-flexed, hands reaching toward the ankles.", pelvis: "Imprinted", spine: "Thoracic flexion", breathing: "Alternating scissor rhythm, one breath per switch.", targetMuscles: "Hip flexors, hamstrings (rhythmic lengthening), abdominals (stabilizing).", focus: "Hip flexor/hamstring dissociation from a stable, flexed spine.", modifications: ["Bend the legs slightly.", "Arms reaching by the sides.", "Shoulders on the Arc Barrel.", "Spine Supporter — develops abdominal strength and/or reduces neck tension due to weakness in the cervical flexors or abdominals.", "Pelvis on the barrel.", "Hold a circle over the chest.", "Legs laterally rotated.", "Flex-Band around the foot."] , script: { lines: ["Let's move into Scissors. Come to supine flexion, legs extended to the ceiling, hands reaching toward your ankles.", "Scissor your legs, reaching one long and one toward your chest, switching with each breath.", "Keep your abdominals holding your spine flexed and stable — the movement comes from your hip flexors and hamstrings lengthening rhythmically, not from rocking your pelvis."] } },
    { name: "Shoulder Bridge Prep", level: "Essential", page: "59", startingPosition: "Supine, pelvis and spine neutral.\nKnees flexed, feet on the mat slightly closer to the seat than for Ab Prep.\nLegs parallel and abducted hip-distance apart.\nArms long by the sides, palms down.", pelvis: "Neutral to start, imprinted during the lift", spine: "Neutral", breathing: "Inhale to stay\nExhale to extend the hips and lift the pelvis into bridge position\nInhale to stay\nExhale to flex the hips and lower the pelvis back to the mat.\nOnce mastered, lift one foot slightly off the mat at the top and replace it before lowering.", targetMuscles: "Gluteus maximus, hamstrings, deep abdominals stabilizing the pelvis and spine in neutral.", focus: "Develops core strength and pelvic stability in neutral before adding spinal articulation — first lifting and lowering the pelvis as one piece, then lifting one foot at a time without letting the pelvis tip.", modifications: ["Fitness Circle Resistance Ring between the knees, gently squeezing as the pelvis lifts.", "On the Arc Barrel (Intermediate)."] , script: { lines: ["Let's move into Shoulder Bridge Prep. Come to supine, knees bent, feet flat, closer to your seat than usual, arms long by your sides.", "Exhale to extend your hips and lift your pelvis into a bridge. Inhale to hold. Exhale to lower back down.", "Feel your gluteus maximus and hamstrings extending your hips, and your deep abdominals holding your pelvis and spine in neutral. Lift and lower as one piece first — once that's stable, try lifting one foot slightly at the top without letting your pelvis tip."] } },
    { name: "Roll Over Prep", level: "Essential", page: "61", startingPosition: "Supine, imprinted position, legs on the diagonal, knees flexed and ankles crossed, arms long by the sides.", pelvis: "Imprinted", spine: "Lumbar flexion only", breathing: "Exhale to roll the pelvis slightly off the mat through lumbar flexion, progressing to rolling the spine to the mid-thoracic area\nInhale to roll the spine and pelvis back onto the mat.", targetMuscles: "Deep abdominals, hip flexors.", focus: "Develops the abdominal strength and lumbar mobility needed for full Roll Over, rolling only through the lumbar spine rather than all the way overhead.", modifications: ["Lower and lift the legs with a barrel under the hips, in an imprinted position, to develop abdominal and hip-flexor strength."] , script: { lines: ["Let's move into Roll Over Prep. Come to supine, imprinted, legs on the diagonal, knees bent, ankles crossed.", "Exhale to roll your pelvis slightly off the mat through your lower back. Inhale to roll back down.", "Let your deep abdominals and hip flexors do the lifting — roll only through your lumbar spine here, this is building the strength for the full Roll Over."] } },
    { name: "Heel Squeeze Prone", level: "Essential", page: "63", startingPosition: "Prone, knees flexed 90°, slightly wider than hip-distance, ankles dorsiflexed, heels together.", pelvis: "Neutral", spine: "Neutral", breathing: "Smooth, continuous.", targetMuscles: "Hamstrings, gluteus maximus, deep hip external rotators.", focus: "Isolates glute activation without letting the low back extend.", modifications: ["Circle between the ankles.", "Thin pad under the ASIS."] , script: { lines: ["Let's move into Heel Squeeze Prone. Come to prone, knees bent to ninety degrees, slightly wider than hip-distance, heels together.", "Smooth, continuous breathing — gently squeeze your heels together and release.", "Feel this in your glutes, hamstrings, and the deep external rotators of your hips, and keep your low back quiet — don't let it extend."] } },
    { name: "One Leg Kick Prep", level: "Essential", page: "65", startingPosition: "Prone, hands under the forehead.", pelvis: "Neutral", spine: "Neutral", breathing: "Exhale to flex the knee (plantar flex then dorsiflex the ankle)\nInhale to extend the knee.", targetMuscles: "Hamstrings, gluteus maximus.", focus: "Stabilizing the pelvis in neutral during knee flexion — easier to isolate here than in the full exercise, which adds thoracic extension on propped forearms.", modifications: ["Thin pad under the ASIS to avoid anterior pelvic tilt.", "Avoid the pulsing action of the legs — draw the leg in slowly to ensure proper tracking of the knee."] , script: { lines: ["Let's move into One Leg Kick Prep. Come to prone, hands stacked under your forehead.", "Exhale to flex your knee, pointing then flexing your ankle. Inhale to extend the leg back down.", "Keep your pelvis anchored in neutral while your hamstrings and glutes drive your knee's movement."] } },
    { name: "Breast Stroke", level: "Essential", page: "66", startingPosition: "Prone, pelvis and spine neutral.\nLegs extended along the mat, adducted or abducted hip-distance apart, parallel, ankles plantar-flexed, toes gently pointed.\nArms bent, hands by the shoulders, palms down, scapulae stabilized.", pelvis: "Neutral", spine: "Neutral to extension", breathing: "Exhale to reach the arms forward, shoulder-distance apart, hovering the upper body just above the mat in a long, low line\nInhale to circle the arms out to the sides and back to the hips, opening the rib cage while keeping the bottom rib on the mat\nExhale (starting the next rep) to flex the elbows and reach the hands forward again, diving the torso back to the long low position without returning the head to the mat.\n5–8 reps.", targetMuscles: "Transversus abdominis and pelvic floor\nMid- and upper-back erector spinae concentrically to extend the thoracic spine, eccentrically as the body lowers\nObliques and hip extensors (maintaining pelvic neutrality)\nScapular stabilizers\nPosterior deltoid (holding arm height)\nDeltoids (reaching forward)\nLatissimus dorsi and teres major (as the arms adduct).", focus: "Builds on Breast Stroke Prep's three hand positions into the full circling-arm pattern, extending the thoracic spine while the pelvis and legs stay completely still.\nEngage the abdominals, hamstrings and glutes throughout to stabilize a neutral pelvis\nAvoid lumbar extension or lifting the legs off the mat\nKeep the scapulae stabilized and avoid overextending the cervical spine or gripping the upper traps.", modifications: ["Fitness Circle® between the ankles — gently squeeze as the spine extends, releasing as it returns, for added lower-body resistance.", "Flex-Band exerciser across the mid-back, holding both ends — extend the band out to a T, then back toward the hips, before returning.", "Thin pad under the ASIS to avoid anterior pelvic tilt.", "Upper body off the end of the mat — good for kyphosis, allowing flexion on the forward reach.", "Sponge or ball between the knees to aid adductor connection."] , script: { lines: ["Let's move into Breast Stroke. Come to prone, legs extended and hip-distance apart, hands by your shoulders.", "Exhale to reach your arms forward and hover your upper body in one long low line. Inhale to circle your arms out to the sides and back to your hips, opening your ribcage.", "Engage your abdominals, hamstrings, and glutes to keep your pelvis completely still and your legs on the mat as your erector spinae extend your upper back and your scapular stabilizers keep your shoulders settled."] } },
    { name: "Saw", level: "Essential", page: "69", startingPosition: "Seated upright, pelvis and spine neutral. Legs long and abducted slightly wider than shoulder-distance apart, ankles dorsiflexed. Arms reaching out to the sides, palms forward.", pelvis: "Neutral", spine: "Axial elongation with flexion/rotation", breathing: "Inhale to rotate the spine around its vertical axis, keeping the pelvis still, reaching the arms to the corners\nExhale to sequentially articulate the spine into flexion from the head, reaching the front arm toward the baby toe as the back arm medially rotates and reaches to the back corner, eyes down, pelvis staying vertical\nInhale to roll up through the spine, sequentially articulating out of flexion from tail to head, reaching the back arm behind and stabilizing the scapulae\nExhale to rotate the spine to face forward, back arm rotating laterally to return to the start, palms facing forward\nRepeat to the other side. Complete 3–5 repetitions each way.", targetMuscles: "Contralateral internal and external obliques concentrically to rotate the spine; rectus abdominis and obliques concentrically to initiate flexion, erector spinae eccentrically to control it; erector spinae concentrically to initiate the roll up; rectus abdominis and obliques eccentrically on the roll up; scapular stabilizers.", focus: "Four distinct phases, not just 'rotate then reach' — rotate first with the spine vertical, fold forward reaching past the baby toe, roll back up through the spine, then rotate back to face forward before switching sides.", modifications: ["Sit on a cushion or the mat's edge."] , script: { lines: ["Let's move into Saw. Come to seated tall, legs open wider than shoulder-distance, arms out to the sides.", "Inhale to rotate your spine, keeping your pelvis square and still. Exhale to fold forward, reaching your front hand past your little toe, like sawing it off, back arm rotating behind you.", "Inhale to roll back up through your spine, tail to head; exhale to rotate back to face forward. Feel your obliques driving the rotation and your erector spinae powering the roll back up."] } },
    { name: "Neck Pull Prep", level: "Essential", page: "73", startingPosition: "Seated vertical, pelvis neutral, legs extended with ankles dorsiflexed (or knees bent).\nHands at the forehead or behind the head, elbows wide, scapulae stabilized.", pelvis: "Neutral to posterior tilt during the roll", spine: "Lumbar flexion only", breathing: "Exhale to roll the ASIS away from the femurs and flex the lumbar spine as low as flat abdominals can be maintained, without resting the lumbar spine on the mat\nInhale to maintain the flexion and breathe into the sides of the ribcage\nExhale to flex the torso forward over the legs, bringing the weight onto the sit-bones\nInhale to sequentially lengthen the spine from tailbone to head, returning to neutral.", targetMuscles: "Abdominals, hip flexors.", focus: "Develops the abdominal strength needed for the complete Neck Pull, working the lumbar roll-back and forward fold without the full supine-to-seated roll up.", modifications: ["Hands behind the head instead of at the forehead."] , script: { lines: ["Let's move into Neck Pull Prep. Come to seated tall, legs extended, hands at your forehead or behind your head.", "Exhale to roll your pelvis away from your legs and flex your lower spine as far as you can while keeping your abdominals flat. Inhale to hold and breathe into your ribs. Exhale to fold forward over your legs. Inhale to sequentially roll back up to vertical.", "Your abdominals and hip flexors are doing the work here — this builds the strength for the full Neck Pull's roll-back and fold, no resting your spine on the mat along the way."] } },
    { name: "Obliques Roll Back", level: "Essential", page: "74", startingPosition: "Seated, knees bent, hip-distance apart, arms long at shoulder height, parallel to the floor.", pelvis: "Posterior tilt", spine: "Flexion with rotation", breathing: "Four breaths, alternating sides.", targetMuscles: "Obliques.", focus: "Combines the Half Roll Back articulation with rotation.", modifications: ["Four breaths — creates more awareness of the movement (inhale to stay, exhale to roll the pelvis away from the femurs and rotate, inhale to stay, exhale to return).", "Hands behind the head.", "Circle between the knees.", "Flex-Band around the feet.", "Pad/ball between the knees."] , script: { lines: ["Let's move into Obliques Roll Back. Come to seated, knees bent, hip-distance apart, arms out to the sides at shoulder height.", "Exhale to roll your pelvis back and rotate to one side. Inhale to return to center, then repeat to the other side.", "Combine the roll-back from Half Roll Back with your obliques adding the rotation — keep both sit-bones grounded evenly."] } },
    { name: "Side Kick", level: "Essential", page: "78", startingPosition: "Side-lying, pelvis and spine neutral. Legs extended with hips flexed slightly to angle the legs forward for balance. Ankles dorsiflexed. Top leg abducted level with the hip. Bottom arm long, supporting the head, palm down. Top hand resting in front of the chest on the mat for stability. Scapulae stabilized.", pelvis: "Neutral", spine: "Neutral alignment", breathing: "Inhale for two counts, ankle staying dorsiflexed: maintain torso stabilization and flex the top hip, reaching the leg forward, reaching a little further on the second count\nExhale to stabilize the pelvis in neutral and extend the hip, reaching the leg back and plantar flexing the ankle, gently pointing the toes.", targetMuscles: "Obliques and erector spinae stabilizing pelvis and spine in neutral; obliques and multifidus preventing rotation; hip flexors concentrically reaching the leg forward; hip extensors concentrically reaching it back; hip abductors maintaining the leg at a constant height; scapular stabilizers.", focus: "Hip dissociation in the sagittal plane while the pelvis and torso stay completely still — the ankle dorsiflexes on the forward kick and plantar flexes on the reach back, it isn't just a straight foot throughout.", modifications: ["Flex the bottom knee.", "Rest the head on the bottom hand.", "Both hands on the head."] , script: { lines: ["Let's move into Side Kick. Come to side-lying, body in one long line, head resting on your extended bottom arm, top leg lifted level with your hip.", "Inhale for two counts, ankle flexed, as your hip flexors kick your top leg forward, reaching a little further on the second count. Exhale as your hip extensors sweep it back, pointing your ankle as it reaches behind you.", "Kick front without losing your pelvis — your obliques and glutes keep your hips stacked and still the whole time your leg is moving."] } },
    { name: "Side Leg Lift Series", level: "Essential", page: "80", startingPosition: "Side-lying, legs extended in line with the torso, plantar-flexed.", pelvis: "Neutral", spine: "Neutral alignment (lateral flexion in the last position only)", breathing: "Smooth, continuous through each position.", targetMuscles: "Gluteus medius/minimus (abduction), adductors (the lower leg in staggered work), obliques (lateral flexion).", focus: "Frontal-plane hip stability across five positions without letting the pelvis roll.", positions: [
      { label: "Top leg abduction", detail: "" },
      { label: "Top leg circles", detail: "" },
      { label: "Staggered legs", detail: "Top leg forward, bottom leg back — trains the lower leg's adductors as it lifts to meet the top." },
      { label: "Both legs together", detail: "" },
      { label: "Both legs with lateral flexion", detail: "Legs lift together as in the position before, adding a lateral flexion of the upper body — the top arm reaches along the legs toward the feet as the torso side-bends, then lengthens back down on the return." },
    ], modifications: ["Flex the bottom leg.", "Adduction with a circle.", "Abduction with a circle.", "Flex-Band around the top foot or both feet."] , script: { lines: ["Let's move into the Side Leg Lift Series. Come to side-lying, legs extended in line with your torso.", "We'll move through five positions — top leg lifting, top leg circling, staggered legs, both legs together, then both legs with a side-bend — smooth continuous breathing throughout each.", "Feel your gluteus medius and minimus doing the lifting, your adductors working as the lower leg meets the top in Staggered Legs, and your obliques adding the side-bend in the last position. Keep your pelvis stacked and still through all five — don't let it roll back or forward as your legs move."] } },
    { name: "Spine Stretch Forward", level: "Essential", page: "90", startingPosition: "Seated, legs slightly wider than shoulder-distance, ankles dorsiflexed.", pelvis: "Neutral", spine: "Axial elongation to flexion", breathing: "Inhale to stay\nExhale to articulate the spine into flexion from the head\nInhale to stay and breathe into the ribcage\nExhale to sequentially return to vertical from the tail up.", targetMuscles: "Abdominals (flexion control), erector spinae (eccentric lengthening).", focus: "Segmental flexion of the spine while keeping the pelvis anchored and legs still.", modifications: ["Sit on a cushion, raised mat, or barrel.", "Two breaths — exhale to roll down, inhale to roll up, to speed up the exercise.", "Hands on top of a circle.", "Against a wall, sitting or standing."] , script: { lines: ["Let's move into Spine Stretch Forward. Come to seated tall, legs slightly wider than shoulder-distance, ankles flexed.", "Inhale to grow tall. Exhale to articulate your spine forward into flexion, starting from your head. Inhale to stay and breathe into your ribcage. Exhale to sequentially roll back up to vertical from your tailbone.", "Grow two inches taller before you round forward, letting your abdominals control the flexion and your erector spinae lengthen eccentrically as you go — imagine draping over a large beach ball rather than collapsing onto it."] } },
    { name: "Teaser Prep", level: "Essential", page: "96", startingPosition: "Half roll down\nFeet on the mat (4 breaths) progressing to one foot on the mat, then legs in the air.", pelvis: "Neutral to posterior tilt during the lift", spine: "Sequential flexion", breathing: "One breath per phase.", targetMuscles: "Deep abdominals, hip flexors.", focus: "Builds the balance point and abdominal strength needed for full Teaser.", modifications: ["Reach the arms low by the hip.", "Circle between the ankles.", "Flex-Band around the feet.", "Pad/ball between the ankles/knees."] , script: { lines: ["Let's move into Teaser Prep. Come to a half roll-down, feet on the mat, arms reaching forward.", "Exhale to curl your upper body up toward your knees, finding your balance point. Inhale to lower back down with control.", "Let your deep abdominals and hip flexors do the lifting — this is building the balance and strength for the full Teaser, don't rush toward lifting your legs before this feels stable."] } },
    { name: "Single Leg Extension", level: "Essential", page: "97", startingPosition: "Prone, hands under the forehead, legs extended long, hip-distance apart, slightly laterally rotated, plantar-flexed.", pelvis: "Neutral", spine: "Neutral", breathing: "Smooth, continuous, alternating legs.", targetMuscles: "Gluteus maximus, hamstrings.", focus: "Hip extension strength while the pelvis stays completely level and still.", modifications: ["Prone on the Arc Barrel.", "Reach both legs off the mat together.", "Legs parallel."] , script: { lines: ["Let's move into Single Leg Extension. Come to prone, hands under your forehead, legs extended long, hip-distance apart.", "Smooth, continuous breathing — lift one leg, then the other, alternating.", "Keep your pelvis completely level and still — feel your gluteus maximus and hamstrings doing the lifting, this is about hip extension strength, not how high the leg lifts."] } },
    { name: "Swan Dive Prep", level: "Essential", page: "99", startingPosition: "Prone, hands by the shoulders, legs slightly laterally rotated, plantar-flexed.", pelvis: "Neutral", spine: "Extension", breathing: "Prep on 2–4 breaths.", targetMuscles: "Erector spinae, gluteus maximus, deep back extensors.", focus: "Builds the thoracic extension strength and control needed for the rocking Swan Dive.", modifications: ["Prep on 4 breaths.", "Prep on 2 breaths.", "With a slow rock.", "On the Arc Barrel."] , script: { lines: ["Let's move into Swan Dive Prep. Come to prone, hands by your shoulders, legs slightly turned out.", "Inhale to lengthen and lift your chest. Exhale to lower back down with control.", "Lengthen out of your low back before you lift — the lift comes from your erector spinae and deep back extensors in your upper back, with your glutes staying soft."] } },
    { name: "Swimming Prep", level: "Essential", page: "101", startingPosition: "Prone, legs extended hip-distance apart, slightly laterally rotated, arms extended overhead, shoulder-distance apart.", pelvis: "Neutral", spine: "Extension", breathing: "Building toward staccato breathing.", targetMuscles: "Erector spinae, gluteus maximus, shoulder extensors, deep back stabilizers.", focus: "Isolates each limb pattern before combining into full Swimming.", positions: [
      { label: "Single leg extension", detail: "" },
      { label: "Double leg extension", detail: "" },
      { label: "Single arm extension", detail: "" },
      { label: "Double arm extension", detail: "" },
      { label: "Contralateral arm-leg pairs", detail: "Opposite arm and leg extend together — the final stage before combining into full Swimming." },
    ], modifications: ["On hands and knees — with the spine stabilized in neutral and knees hip-distance apart, reach the opposite arm and leg; more suitable for those with less range of motion at the hips or shoulders, or who tend to extend the lumbar spine.", "Upright arm movement — kneeling or sitting on the heels with the arms extended overhead toward the ceiling, alternating arms in a swimming motion; useful for kyphosis or tight pectorals/latissimus dorsi.", "Upper body off the end of a raised mat.", "Legs parallel."] , script: { lines: ["Let's move into Swimming Prep. Come to prone, legs extended hip-distance apart, arms extended overhead.", "We'll isolate each piece first — one leg lifting, then both legs, then one arm, then both arms, then opposite arm and leg together — building toward the staccato breath of full Swimming.", "Keep your pelvis and low back quiet throughout — the lift comes from your erector spinae, gluteus maximus, and shoulder extensors, not from arching your lumbar spine."] } },
    { name: "Leg Pull Front Prep", level: "Essential", page: "103", startingPosition: "Quadruped — on hands and knees, spine and pelvis neutral. Knees directly under the hips, legs adducted, weight on the balls of the feet. Arms extended directly under the shoulders, palms down, fingers pointing forward.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to stay\nExhale to adduct the legs and lift the knees off the mat about two inches, maintaining a neutral spine\nInhale to stay\nExhale to lower the knees back onto the mat.", targetMuscles: "Deep core stabilizers, shoulder stabilizers, glutes, quadriceps.", focus: "Stays on hands and knees for this whole progression — the push-up/plank position is only the last and hardest modification, not the starting shape.", modifications: ["Keep the knees lifted off the mat and alternate slightly lifting one foot, then the other.", "Knees further back than the pelvis, challenging core stability further.", "Knees further back than the hips, extending fully to a push-up position.", "From full push-up position, omit the rock back and forth — just practice lifting one leg at a time.", "Hands on the Arc Barrel."] , script: { lines: ["Let's move into Leg Pull Front Prep. Come to hands and knees, knees directly under your hips, weight on the balls of your feet, arms extended under your shoulders.", "Inhale to stay. Exhale to squeeze your legs together and lift your knees about two inches off the mat, keeping your spine neutral and your deep core stabilizers engaged. Inhale to stay, exhale to lower back down.", "This stays on your hands and knees the whole time — the full push-up or plank position only comes in later, as the hardest progression, once this feels stable."] } },
    { name: "Seal", level: "Essential", page: "113", startingPosition: "Seated, weight back on the sit bones, legs laterally rotated, hips/knees flexed, soles of the feet together off the mat, hands reaching through the legs to hold the outside of the ankles.", pelvis: "Posterior tilt", spine: "Flexion — ball shape", breathing: "Inhale to roll back and clap the feet together three times\nExhale to roll forward and clap the feet together three times.", targetMuscles: "Deep abdominals (maintaining the C-curve through the roll).", focus: "A playful balance-and-roll finisher that reinforces the C-curve under momentum.", modifications: ["Omit the claps.", "Hold on to the outside of the legs."] , script: { lines: ["Let's move into Seal. Come to seated, weight back on your sit bones, knees bent and turned out, soles of your feet together, hands reaching through your legs to hold your ankles.", "Inhale to roll back and clap your feet together three times. Exhale to roll back up to balance and clap three more times.", "Keep your deep abdominals holding a consistent C-curve through the roll — this is a playful finisher, so let the momentum help, but stay controlled."] } },
    { name: "Side Bend Prep", level: "Essential", page: "114", startingPosition: "Supporting knee on the mat, hand in line with the front knee, top leg slightly laterally rotated.", pelvis: "Neutral", spine: "Lateral flexion", breathing: "Exhale to lift the pelvis toward the ceiling\nInhale to lower back to the mat.", targetMuscles: "Obliques (lateral chain), shoulder stabilizers of the supporting arm.", focus: "Builds lateral-flexion strength and shoulder stability before the full standing/side Side Bend.", modifications: ["Knees stacked on top of each other.", "Four breaths — to slow down the pace of the exercise.", "Position of feet — starting with the feet closer to the body requires more lateral flexion; starting further from the body requires less lateral flexion."] , script: { lines: ["Let's move into Side Bend Prep. Come to kneeling on one knee, your hand in line with that knee, top leg extended and slightly turned out.", "Exhale to lift your pelvis up toward the ceiling. Inhale to lower back down to the mat.", "Lift through your obliques along your waistline, using your supporting shoulder's stabilizers to stay stable — this builds toward the full standing Side Bend."] } },
    { name: "Push Up Prep", level: "Essential", page: "122", startingPosition: "Standing at the end of the mat, walking hands out to plank, legs together.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Inhale down\nExhale to press up\nSmooth breath through the roll down/up.", targetMuscles: "Pectorals, triceps, deep core stabilizers, scapular stabilizers.", focus: "A full-body flow linking a roll-down, a plank/push-up, and a roll-up — tests scapular and core stability under load.", modifications: ["Prep with knees down.", "Against a wall.", "Reach the elbows directly back (arabesque prep).", "Hands together."] , script: { lines: ["Let's move into Push Up Prep. Come to standing at the end of your mat.", "Roll down through your spine, walk your hands out to a plank, then walk them back and roll back up to standing.", "Keep your spine long and your deep core stabilizers connected the whole way down and up, with your pectorals and triceps holding the plank — this tests your scapular and core stability under load."] } },
  ],
  intermediate: [
    { name: "Slow Double Leg Stretch", level: "Intermediate", page: "52", startingPosition: "Supine, imprinted position. Legs bent in the air, laterally rotated, ankles plantar flexed, toes gently pointed together, knees apart in a diamond shape. Hands pressed gently against the outside of the knees, scapulae stabilized.", pelvis: "Imprinted", spine: "Thoracic flexion", breathing: "Inhale to stay\nExhale to lengthen the back of the neck, stabilize the scapulae and contract the abdominals to flex the thoracic spine, legs staying in the diamond shape\nInhale to maintain that flexion and extend the legs as low as imprint can be maintained, adducted and parallel, simultaneously reaching the arms out by the sides, level with the shoulders, palms down\nExhale to reach the arms overhead, simultaneously rotating the legs laterally and dorsiflexing the feet\nInhale to circle the arms open and around back to the hips while rotating the legs back to parallel and pointing the feet\nExhale to return to the starting position by lowering the upper body to the mat, flexing the knees, rotating the legs laterally, and returning the hands to the knees.", targetMuscles: "Rectus abdominis and obliques concentrically creating the thoracic flexion, isometrically sustaining it against the weight of the arms and stabilizing the pelvis against the weight of the legs, eccentrically controlling the return down; lateral and medial rotators of the hip joints; hip flexors eccentrically as the legs extend; scapular stabilizers.", focus: "A full-body sequence, not just an arm/leg extend-and-return — the legs rotate between lateral and parallel while the arms circle overhead and back, all synchronized with the breath.", modifications: ["Flex-Band around the feet.", "Maintain the lateral rotation of the legs throughout.", "Shoulders on the Arc Barrel — assists the abdominals with thoracic flexion; resting the head on the Barrel as well eliminates neck tension while encouraging thoracic flexion.", "Spine Supporter — develops abdominal strength and/or reduces neck tension due to weakness in the cervical flexors and/or abdominals."] , script: { lines: ["Let's move into Slow Double Leg Stretch. Come to supine, imprinted, legs bent and turned out in a diamond shape, hands pressed gently against the outside of your knees.", "Exhale to curl your thoracic spine up using your rectus abdominis and obliques, legs staying put. Inhale to extend your legs low and reach your arms out to the sides.", "Exhale to reach your arms overhead as your legs rotate out and your feet flex; inhale to circle your arms back to your hips as your legs rotate parallel and your feet point. Exhale to lower back down, bending your knees and turning them out again to finish.", "Keep your deep abdominals engaged throughout to hold the curl steady while your arms and legs do the moving."] } },
    { name: "Shoulder Bridge", level: "Intermediate", page: "58", startingPosition: "Supine, pelvis and spine neutral. Knees flexed, feet on the mat slightly closer to the seat than for Ab Prep. Legs parallel and abducted hip-distance apart. Arms long by the sides, palms down, scapulae stabilized.", pelvis: "Neutral throughout — no articulation, this is a direct hip-extension lift", spine: "Neutral — stays neutral the whole exercise, unlike Hip Rolls", breathing: "Inhale to stay\nExhale to stabilize the pelvis and spine in neutral and extend the hips, lifting the pelvis off the mat into a bridge from shoulders to knees\nInhale to maintain a level pelvis and lift one foot, flexing the hip and plantar flexing the ankle, then extending the knee to reach the toes to the ceiling\nExhale to dorsiflex the ankle and extend the leg at the hip, lowering it as low as neutral pelvis can be maintained\nInhale to plantar flex the ankle, pointing the toes, and flex the leg back up at the hip — repeat the extension and flexion twice more\nExhale to flex the knee and lower the foot back to the mat, articulating through the foot\nRepeat on the other leg. Complete 2–3 repetitions on each side\nTo finish: inhale to stay and lengthen the spine in neutral\nExhale to flex the hips and lower the pelvis back onto the mat.", targetMuscles: "Rectus abdominis and obliques preventing anterior pelvic tilt; hip extensors concentrically extending the hips and lifting the pelvis; hip extensors and multifidus of the supporting leg isometrically preventing the pelvis from rotating as the other leg lifts; hip flexors of the gesture leg eccentrically as it lowers, concentrically as it lifts; scapular stabilizers.", focus: "No spinal articulation here, unlike Hip Rolls — the pelvis lifts and lowers as one unit, driven by hip extension, while the pelvis stays level and non-rotating as each leg extends and lowers.", modifications: ["Circle between the knees.", "On the Arc Barrel."] , script: { lines: ["Let's move into Shoulder Bridge. Come to supine, knees bent, feet hip-distance apart, arms long by your sides.", "Exhale to extend your hips and lift your pelvis directly into a bridge — no rolling through your spine, this comes from your glutes and hamstrings extending your hips as one piece.", "Inhale to lift one foot and extend that knee to the ceiling; exhale to lower the leg as low as you can without your pelvis dropping; inhale to flex it back up. Repeat twice more, then lower the foot and switch legs.", "Keep your pelvis level and non-rotating the whole time one leg is moving — your supporting-side glutes and deep stabilizers are doing that work."] } },
    { name: "Roll Over", level: "Intermediate", page: "60", startingPosition: "Supine, legs extended on the diagonal, arms long by the sides.", pelvis: "Imprinted/posterior tilt", spine: "Spinal articulation", breathing: "Inhale to hinge the legs toward the torso\nExhale to roll the spine up and overhead\nInhale to lift and abduct the legs\nExhale to roll the spine back down.", targetMuscles: "Deep abdominals, hip flexors, erector spinae (eccentric control on the way down).", focus: "Full spinal articulation overhead and back down — a bigger, more demanding cousin of Roll Up.", faults: ["Momentum swinging the legs overhead — control the lift with the abdominals, not momentum.", "Landing hard on the neck — roll only to the shoulder blades, not the cervical spine."], modifications: ["Full roll over with a barrel.", "Legs laterally rotated.", "Flex the feet on the roll-down.", "Circle between the ankles.", "Pad/ball between the ankles/knees."] , script: { lines: ["Let's move into Roll Over. Come to supine, legs extended on the diagonal, arms long by your sides.", "Inhale to hinge your legs toward your torso. Exhale to roll your spine up and overhead. Inhale to open your legs. Exhale to roll back down.", "Control the lift with your deep abdominals and hip flexors, not momentum, and let your erector spinae control the roll down only to your shoulder blades, never onto your neck."] } },
    { name: "One Leg Kick", level: "Intermediate", page: "64", startingPosition: "Front of the body facing the mat, upper body propped up on the forearms, one long line from tailbone to crown. Legs adducted or abducted hip-distance apart, parallel, ankles plantar flexed, toes gently pointed. Hips in extension with the ASIS off the mat and pubic bone on the mat. Scapulae stabilized.", pelvis: "Neutral", spine: "Thoracic extension", breathing: "Exhale to stabilize the pelvis as one knee flexes twice with controlled pulses — first pulse with the ankle plantar flexed, second pulse with the ankle dorsiflexed\nInhale to extend the knee, plantar flexing the ankle again as the leg returns to the mat\nRepeat with the other leg. Complete 5–8 repetitions with each leg.", targetMuscles: "Obliques preventing spinal extension; hip extensors isometrically keeping the back of the pelvis drawn toward the back of the femurs; obliques and multifidus stabilizing the spine against rotation; hamstrings concentrically as the knee flexes, eccentrically as it extends; scapular stabilizers, especially serratus anterior.", focus: "Knee flexion control while holding thoracic extension and pelvic stability — the ankle changes from plantar flexed to dorsiflexed between the two pulses, it doesn't stay pointed throughout.", faults: ["Pulsing the legs too fast/uncontrolled — slow the tempo.", "Low back sagging — keep the ASIS lifted."], modifications: ["Avoid the pulsing action of the legs — draw the leg in slowly to ensure proper tracking of the knee."] , script: { lines: ["Let's move into One Leg Kick. Come to prone on your forearms, legs hip-distance apart, hips extended, ASIS lifted off the mat.", "Exhale for two pulses, kicking your heel toward your seat — ankle pointed on the first pulse, flexed on the second. Inhale to extend the leg back down, pointing the ankle as it returns.", "Keep your pace controlled, not fast and sloppy, and use your obliques and hip extensors to keep your low back lifted — don't let it sag."] } },
    { name: "Open Leg Rocker", level: "Intermediate", page: "70", startingPosition: "Balanced seated, weight back of the sit bones, J-curve, legs extended in a V, shoulder-distance apart, plantar-flexed, hands holding the ankles, eyes toward the feet.", pelvis: "Posterior tilt", spine: "Flexion", breathing: "Inhale to roll back\nExhale to roll up to balance.", targetMuscles: "Deep abdominals, hip flexors (holding the V), hamstrings (flexibility).", focus: "Combines the balance challenge of Rolling Like a Ball with straight-leg control.", modifications: ["Bend the knees during the balance.", "Bend the knees throughout.", "Hold the toes instead of the ankles.", "Circle between the ankles."] , script: { lines: ["Let's move into Open Leg Rocker. Come to seated, balanced just back of your sit bones, legs open in a V, hands holding your ankles.", "Inhale to roll back. Exhale to roll back up to balance.", "Keep your deep abdominals scooped and your hip flexors holding the V as you roll — don't let your low back overarch at the top, and roll smoothly along the length of your spine."] } },
    { name: "Neck Pull", level: "Intermediate", page: "72", startingPosition: "Supine, pelvis and spine neutral. Legs extended along the mat, adducted or abducted hip-distance apart, ankles dorsiflexed. Hands behind the head, scapulae stabilized.", pelvis: "Neutral to posterior tilt during the roll", spine: "Sequential flexion", breathing: "Inhale to initiate with cranio-vertebral flexion (a head nod), stabilize the scapulae, then flex through the thoracic spine, elbows wide\nExhale to continue rolling the spine off the mat sequentially through imprint, until the weight is on top of the sit-bones and the torso is flexed forward over the legs\nInhale to keep the pelvis vertical and lengthen the spine to neutral, sequentially articulating from tail to head\nExhale to maintain scapular stabilization and initiate the roll down by rolling the ASIS away from the front of the femurs and flexing the spine, rolling down to the mat through flexion one vertebra at a time, pelvis returning to neutral once the lower thoracic reaches the mat.", targetMuscles: "First rectus abdominis and obliques, then hip flexors concentrically to roll up; erector spinae concentrically to lengthen the spine to neutral once seated; hip flexors eccentrically, then rectus abdominis and obliques concentrically to start rolling down, then eccentrically to complete it; hip extensors concentrically as the back of the pelvis moves toward the back of the femurs; scapular stabilizers.", focus: "Four distinct phases, not just 'roll up, roll down' — curl into flexion, continue rolling all the way up and forward over the legs, lengthen back to vertical sitting, then hinge the pelvis back first to initiate the roll down.", faults: ["Yanking on the head/neck — elbows stay wide, hands lightly support the head only."], modifications: ["Hands on the forehead.", "Reach arms forward during the roll up.", "Bend the knees.", "Circle between the knees.", "Flex-Band around the feet.", "With a hinge back.", "Pad/ball between the knees."] , script: { lines: ["Let's move into Neck Pull. Come to supine, legs extended, hip-distance apart, hands lightly behind your head, elbows wide.", "Exhale to nod your chin and curl through your rectus abdominis and obliques, continuing to roll all the way up and forward over your legs, weight coming onto your sit-bones. Inhale to lengthen your spine back up to vertical sitting, using your erector spinae.", "Exhale to roll back down — initiate by rolling your pelvis away from your legs first, then flex through your spine one vertebra at a time, all the way back to the mat.", "Elbows stay wide the whole time, hands just lightly supporting your head, never pulling on your neck."] } },
    { name: "Jack Knife", level: "Intermediate", page: "76", startingPosition: "Supine, legs extended on the diagonal, plantar-flexed, arms long by the sides.", pelvis: "Imprinted/posterior tilt", spine: "Spinal articulation", breathing: "Inhale to lift the legs and hips straight up overhead\nExhale to roll down with control.", targetMuscles: "Deep abdominals, gluteus maximus and hamstrings (reaching the legs toward the ceiling), scapular stabilizers.", focus: "A powerful, controlled overhead lift that demands strong abdominal support to avoid momentum.", modifications: ["Use the Arc Barrel.", "Alternative breathing pattern (reverse the inhale/exhale)."] , script: { lines: ["Let's move into Jack Knife. Come to supine, legs extended on the diagonal, arms long by your sides.", "Inhale to lift your legs and hips straight up overhead. Exhale to roll back down with control.", "Keep the lift powered by your deep abdominals, with your gluteus maximus and hamstrings reaching the legs skyward, not by swinging — this is a big, controlled overhead lift."] } },
    { name: "Double Leg Kick", level: "Intermediate", page: "88", startingPosition: "Prone, pelvis and spine neutral, head turned to one side. Legs adducted or abducted hip-distance apart, parallel, knees extended, ankles plantar flexed, toes gently pointed. Hands resting behind the back as high as is comfortable, shoulders relaxed forward.", pelvis: "Neutral", spine: "Extension", breathing: "Exhale to stabilize the pelvis and flex both knees three times with controlled pulses\nInhale to extend the knees while maintaining adduction, then laterally rotate and abduct the legs to shoulder-width apart, extending the hips — simultaneously stabilize the scapulae, extend the thoracic spine, and lengthen the arms to reach toward the feet, palms facing the body\nTo transition into the next repetition, exhale to turn the head to the other side as the upper body and legs lengthen back down onto the mat, bringing the legs parallel and adducted again before the next set of knee-flex pulses\nComplete 4–6 repetitions to each side, finishing with an exhale to lengthen the upper body, arms and legs down onto the mat.", targetMuscles: "Obliques and hip extensors stabilizing the pelvis in neutral during the pulses; hamstrings concentrically as the knees flex; hip extensors concentrically to lift the legs; erector spinae concentrically to extend the spine; obliques preventing overextension; scapular retractors opening the front of the shoulders; latissimus dorsi and teres major bringing the shoulders into extension.", focus: "The legs don't stay parallel through the whole exercise — on the big extension, they laterally rotate and open to shoulder-width as the hips extend and the arms reach toward the feet, and the head switches to the other side with every repetition.", modifications: ["Torso only.", "Legs only.", "Avoid pulsing the legs if there's knee sensitivity."] , script: { lines: ["Let's move into Double Leg Kick. Come to prone, head turned to one side, hands resting behind your back.", "Exhale for three controlled pulses, flexing both knees toward your seat. Inhale to extend your knees, then turn your legs out and open them to shoulder-width as your hips extend — reach your arms back toward your feet as your upper back extends, using your erector spinae and shoulder extensors.", "Exhale to lengthen back down, turning your head to the other side and bringing your legs back to parallel before the next set of pulses.", "Feel your hamstrings and glutes driving the kick, and your latissimus dorsi and rhomboids opening your chest as your arms reach back — keep the pulses controlled, not rushed."] } },
    { name: "Teaser Series 1", level: "Intermediate", page: "92", startingPosition: "Supine/tabletop progressing to legs extended on the diagonal, parallel, plantar-flexed, arms long overhead.", pelvis: "Neutral to posterior tilt during the lift", spine: "Sequential flexion", breathing: "Inhale to sequentially roll up into the full Teaser V and balance\nExhale to roll back down.", targetMuscles: "Deep abdominals, hip flexors.", focus: "Full Teaser — simultaneous spinal roll-up and straight-leg lift to a balanced V, holding the balance point from Teaser Prep.", faults: ["Legs dropping below the torso line — the V angle should stay balanced, not legs-heavy.", "Using momentum to fling up — slow the lift and lead with the abdominals."], modifications: ["Reach the arms low by the hip.", "Fitness Circle Resistance Ring between the ankles — adds lower-body resistance.", "Flex-Band around the feet.", "Sponge or ball between the ankles or knees, to aid adductor connection."] , script: { lines: ["Let's move into Teaser. Come to supine, legs extended on the diagonal, arms reaching long overhead.", "Inhale to sequentially roll your spine and legs up together into the full Teaser V, and balance. Exhale to roll back down with control.", "Keep your V angle balanced rather than legs-heavy, and lead the lift with your deep abdominals and hip flexors, not momentum."] } },
    { name: "Swan Dive", level: "Advanced", page: "98", startingPosition: "Prone, pelvis and spine neutral.\nLegs extended along the mat, abducted shoulder-width apart and slightly laterally rotated, ankles plantar-flexed, toes gently pointed.\nArms bent, hands by the shoulders, palms down, scapulae stabilized.", pelvis: "Neutral", spine: "Extension", breathing: "Inhale to stabilize the scapulae and lengthen the spine into extension, hips possibly lifting off the mat at the top\nExhale to dive forward, initiating with the legs reaching back and up as the torso rocks forward onto the lower ribs, arms reaching forward, palms up\nInhale to keep the arms reaching and rock back up into extension\nRock 5–8 times\nTo finish: inhale to place the hands on the mat to support the torso on the last rock up\nExhale as the legs stay on the mat and the spine lengthens down to prone.", targetMuscles: "Erector spinae and hip extensors maintaining the shape throughout the rock; obliques preventing overextension of the lumbar spine; scapular stabilizers.", focus: "A dynamic rocking extension, not a simple lift-and-lower — exhale drives the dive forward (legs reaching back and up), inhale powers the rock back up into extension; catch the rock every time rather than collapsing.", faults: ["Collapsing/crashing on the rock down — control the eccentric lower every time.", "Hyperextending the low back instead of distributing extension along the whole spine."], modifications: ["With a slow rock only (no dive).", "On the Arc Barrel.", "\"Rock and catch\" variation for beginners finding the rhythm."], notes: "Listed at Advanced level in this manual (p.98), though sometimes taught as a late-Intermediate progression." , script: { lines: ["Let's move into Swan Dive. Come to prone, legs slightly turned out, hands by your shoulders.", "Inhale to lengthen your spine into extension, using your erector spinae and hip extensors. Exhale to dive forward, reaching your legs back and up as your torso rocks onto your lower ribs, arms reaching forward.", "Inhale to rock back up into extension, keeping your arms reaching. Catch the rock every time rather than collapsing into it, and distribute the extension along your whole spine, not just your low back."] } },
    { name: "Swimming", level: "Intermediate", page: "100", startingPosition: "Prone, legs extended hip-distance apart, slightly laterally rotated, arms extended overhead, shoulder-distance apart.", pelvis: "Neutral", spine: "Extension", breathing: "Staccato breathing — 5 counts inhale, 5 counts exhale, matching the flutter kick rhythm.", targetMuscles: "Erector spinae, gluteus maximus, shoulder extensors, deep stabilizers of the whole posterior chain.", focus: "Sustained thoracic extension with contralateral arm/leg flutter — an endurance test for the whole back line.", modifications: ["Upper body off the end of a raised mat.", "On the Arc Barrel.", "Decrease speed.", "Increase speed.", "Staccato breath — helps promote the full breath pattern and avoid holding the breath."] , script: { lines: ["Let's move into Swimming. Come to prone, legs extended hip-distance apart, arms reaching overhead.", "Staccato breathing — five counts in, five counts out — as you flutter opposite arm and leg continuously.", "Lift from your erector spinae to open your chest, let your gluteus maximus and shoulder extensors drive the flutter, and keep your pelvis heavy on the mat the entire time."] } },
    { name: "Leg Pull Front", level: "Intermediate", page: "102", startingPosition: "Push-up position, front of the body facing the mat, one long line from head to heels, pelvis and spine neutral. Legs extended, adducted and parallel, weight on the balls of the feet. Arms extended directly under the shoulders, palms down, fingers pointing forward, scapulae stabilized.", pelvis: "Neutral", spine: "Neutral", breathing: "Inhale to extend one hip, ankle dorsiflexed, reaching the leg as high as possible while stabilizing the pelvis and spine in neutral\nExhale to further dorsiflex the supporting ankle, shifting the body back in space, while simultaneously plantar flexing the lifted ankle and maintaining hip extension\nInhale to shift the body forward in space, returning the supporting ankle to the start and dorsiflexing the lifted ankle\nExhale to lower the leg onto the ball of the foot, bringing the legs together\nComplete 3–6 repetitions on each side, alternating each time.", targetMuscles: "Rectus abdominis and obliques preventing spinal extension; obliques and multifidus preventing rotation; pectoralis major and scapular stabilizers, especially serratus anterior; hip extensors concentrically lifting the leg; plantar and dorsiflexors of both legs concentrically and eccentrically.", focus: "A whole-body rock, not a static hold — the supporting ankle drives a subtle shift of body weight back and forward in space, while the lifted leg's ankle points and flexes in counter-rhythm to the supporting one.", modifications: ["Without alternating legs — hold the static plank only.", "Hands on the Arc Barrel."] , script: { lines: ["Let's move into Leg Pull Front. Come to a full plank, one long line from your head to your heels, hands under your shoulders.", "Inhale to lift one leg, ankle flexed, as high as you can without losing your neutral pelvis. Exhale to press your supporting ankle down further, shifting your whole body back in space, while your lifted foot points.", "Inhale to shift your body forward again, flexing the lifted ankle back; exhale to lower the leg and bring your feet together.", "This is a whole-body rock, powered by your obliques and pectoralis major holding the plank steady — resist any rotation through your pelvis or hip-hiking as each leg lifts."] } },
    { name: "Hip Twist", level: "Intermediate", page: "106", startingPosition: "Seated, weight back on the sit bones, legs extended, toes pointing up, arms extended behind, fingers pointing outward.", pelvis: "Neutral", spine: "Axial elongation — J-curve", breathing: "Smooth, continuous circular rhythm.", targetMuscles: "Deep abdominals, hip flexors.", focus: "Circular hip control from a supported J-curve seated position.", modifications: ["Rest on the elbows.", "Flex the knees."] , script: { lines: ["Let's move into Hip Twist. Come to seated, weight back on your sit bones, legs extended, arms extended behind you for support.", "Smooth, continuous circular rhythm as your legs circle around.", "Keep your upper body supported and still in its J-curve — your deep abdominals and hip flexors drive the circle at your hips, not your torso rocking."] } },
    { name: "Side Bend", level: "Intermediate", page: "114", startingPosition: "Seated on one hip, top leg slightly laterally rotated, bottom leg on the mat behind the top foot.", pelvis: "Neutral", spine: "Lateral alignment", breathing: "Inhale to lift into the full side plank/lateral flexion\nExhale to lower.", targetMuscles: "Obliques (lateral chain), shoulder stabilizers.", focus: "Full lateral-flexion strength building on Side Bend Prep, holding a straight lateral line.", modifications: ["Position of the feet: closer to the body requires more lateral flexion; further from the body requires less lateral flexion."] , script: { lines: ["Let's move into Side Bend. Come to seated on one hip, top leg turned out, bottom leg tucked behind your top foot.", "Inhale to lift into a full side plank. Exhale to lower back down.", "Hold one straight lateral line from your ankles to your fingertips, lifted by your obliques with your shoulder stabilizers supporting the base arm — no folding at the hips."] } },
    { name: "Push Up", level: "Intermediate", page: "122", startingPosition: "Standing at the end of the mat, spine and pelvis neutral, legs parallel and adducted, arms long by the sides.", pelvis: "Neutral", spine: "Neutral, elongated", breathing: "Smooth breath through the roll down\nInhale to lower the push-up\nExhale to press up.", targetMuscles: "Pectorals, triceps, deep core stabilizers, scapular stabilizers.", focus: "Full flow version of the push-up sequence, including an arabesque-style single-leg lift variation at the top.", modifications: ["Arabesque — as the spine flexes forward, reach one hip into extension with the leg laterally rotated and maintain that position throughout the push-up; as the hands walk back, balance on the supporting leg and roll up through flexion while keeping the hip in extension. Tests balance and stability on three points instead of four.", "Knee bend and rise.", "Hands on the Arc Barrel.", "Smooth, steady breath throughout for beginners still learning the sequence."] , script: { lines: ["Let's move into Push Up. Come to standing at the end of your mat, spine tall, arms long by your sides.", "Roll down through your spine, walk your hands out to a plank, lower into your push-up, press back up, then walk your hands back and roll up to standing.", "Keep your spine long through the whole flow, letting your pectorals and triceps power the push-up — this tests your scapular and core stability under load."] } },
  ],
  advanced: [],
};
